<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api';
import { dateText, downloadMaterial, errorText, moduleText, newApplication, post, statusText, validateApplication, uploadMaterial, validateMaterials, type SaasCatalog } from '../saas';
import SaasPublicFrame from '../components/SaasPublicFrame.vue';
import SaasApplicationFields from '../components/SaasApplicationFields.vue';
const uploading=ref(false);const uploadError=ref(sessionStorage.getItem('saas-material-upload-error')??'');
async function uploadFiles(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files??[]);const validation=validateMaterials(files);if(validation){uploadError.value=validation;input.value='';return}uploading.value=true;uploadError.value='';try{for(const file of files)await uploadMaterial(application.value.id,credentials.trackingSecret,file);sessionStorage.removeItem('saas-material-upload-error');await track();ElMessage.success('申请材料已上传')}catch(e){uploadError.value=errorText(e)}finally{uploading.value=false;input.value=''}}
const credentials=reactive({businessNo:'',trackingSecret:''}); const application=ref<any>(null);const error=ref('');const loading=ref(false);const saving=ref(false);const editing=ref(false);const form=reactive(newApplication());const catalog=ref<SaasCatalog>({cities:[],modules:[]});
async function download(material:any){try{await downloadMaterial(application.value.id,material,credentials.trackingSecret)}catch(e){error.value=errorText(e)}}
async function remove(material:any){try{await ElMessageBox.confirm('移除后可重新上传正确材料，原办理记录继续保留。确认移除？','移除申请材料',{type:'warning',confirmButtonText:'确认移除',cancelButtonText:'取消'});await api(`/saas/applications/${application.value.id}/materials/${material.id}`,{method:'DELETE',body:JSON.stringify({trackingSecret:credentials.trackingSecret})});await track();ElMessage.success('材料已移除')}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}}
async function track(){error.value='';if(!credentials.businessNo.trim()||!credentials.trackingSecret.trim()){error.value='请填写申请编号和查询凭证';return}loading.value=true;try{application.value=await post('/saas/applications/track',credentials);sessionStorage.setItem('saas-application-tracking',JSON.stringify(credentials));editing.value=false}catch(e){application.value=null;error.value=errorText(e)}finally{loading.value=false}}
async function edit(){try{catalog.value=await api('/saas/catalog');const value=application.value;Object.assign(form,{cityCode:value.cityCode,unitName:value.unitName,contactName:value.contactName,contactPhone:value.contactPhone,adminName:value.adminName,adminUsername:value.adminUsername,modules:[...(value.modules??[])],expectedVehicles:value.expectedVehicles,materialNote:value.materialNote});editing.value=true}catch(e){error.value=errorText(e)}}
async function resubmit(){const validation=validateApplication(form);if(validation){error.value=validation;return}saving.value=true;error.value='';try{application.value=await post(`/saas/applications/${application.value.id}/resubmit`,{...form,trackingSecret:credentials.trackingSecret});editing.value=false;ElMessage.success('补正材料已重新提交')}catch(e){error.value=errorText(e)}finally{saving.value=false}}
async function withdraw(){try{await ElMessageBox.confirm('撤回后该申请将停止审核。确认撤回？','撤回申请',{type:'warning',confirmButtonText:'确认撤回',cancelButtonText:'继续保留'});saving.value=true;application.value=await post(`/saas/applications/${application.value.id}/withdraw`,{trackingSecret:credentials.trackingSecret});ElMessage.success('申请已撤回')}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{saving.value=false}}
onMounted(()=>{try{const stored=JSON.parse(sessionStorage.getItem('saas-application-tracking')??'null');if(stored){Object.assign(credentials,stored);track()}}catch{sessionStorage.removeItem('saas-application-tracking')}});
</script>
<template><SaasPublicFrame><h1>开通申请进度</h1><p class="intro">使用申请编号和查询凭证查看审核进度、补正要求及开通结果。</p><el-form label-position="top" @submit.prevent="track"><div class="saas-grid"><el-form-item label="申请编号"><el-input v-model="credentials.businessNo" aria-label="申请编号"/></el-form-item><el-form-item label="查询凭证"><el-input v-model="credentials.trackingSecret" type="password" show-password aria-label="查询凭证"/></el-form-item></div><el-button native-type="submit" :loading="loading" type="primary">查询进度</el-button></el-form><div v-if="error" class="saas-error" role="alert" style="margin-top:18px">{{error}}</div><template v-if="application"><div class="saas-panel" style="margin-top:24px"><div class="saas-heading"><h2>{{application.cityName}} · {{application.businessNo}}</h2><el-tag>{{statusText(application.status)}}</el-tag></div><el-descriptions :column="2" border><el-descriptions-item label="申请单位">{{application.unitName}}</el-descriptions-item><el-descriptions-item label="申请时间">{{dateText(application.createdAt)}}</el-descriptions-item><el-descriptions-item label="业务模块" :span="2">{{moduleText(application.modules)}}</el-descriptions-item><el-descriptions-item label="审核意见" :span="2">{{application.reviewComment||'待省级核验申请信息'}}</el-descriptions-item><el-descriptions-item label="开通结果" :span="2">{{application.status==='APPROVED'?statusText(application.job?.status??application.provisionJob?.status):(application.status==='REJECTED'||application.status==='WITHDRAWN'?'未开通':'待审核通过后执行')}}<span v-if="application.job?.error"> · {{application.job.error}}</span></el-descriptions-item></el-descriptions><p v-if="application.status==='APPROVED'" class="saas-subtle">开通完成后，由省级管理员向指定负责人交付账号激活邀请。</p><div class="saas-actions" style="margin-top:16px"><el-button v-if="application.status==='RETURNED'&&!editing" type="primary" @click="edit">补正并重新提交</el-button><el-button v-if="['SUBMITTED','RETURNED'].includes(application.status)" :loading="saving" @click="withdraw">撤回申请</el-button></div></div><div v-if="editing" class="saas-panel" style="margin-top:18px"><h2>补正申请材料</h2><el-form label-position="top" @submit.prevent="resubmit"><SaasApplicationFields :form="form" :catalog="catalog" lock-city/><div class="saas-actions"><el-button @click="editing=false">取消修改</el-button><el-button native-type="submit" type="primary" :loading="saving">重新提交</el-button></div></el-form></div><div class="saas-panel" style="margin-top:18px"><h2>申请材料</h2><div v-if="uploadError" class="saas-error" role="alert">申请已提交，材料上传未完成：{{uploadError}}</div><el-table :data="application.materials??[]" empty-text="尚未上传附件"><el-table-column label="材料名称" min-width="220"><template #default="{row}">{{row.originalName||row.name}}</template></el-table-column><el-table-column label="大小" width="110"><template #default="{row}">{{Math.ceil(row.size/1024)}} KB</template></el-table-column><el-table-column label="上传时间" min-width="170"><template #default="{row}">{{dateText(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button text type="primary" @click="download(row)">下载</el-button><el-button v-if="['SUBMITTED','RETURNED'].includes(application.status)" text @click="remove(row)">移除</el-button></template></el-table-column></el-table><div v-if="['SUBMITTED','RETURNED'].includes(application.status)" v-loading="uploading" style="margin-top:16px"><label>补充材料 <input type="file" accept="application/pdf,image/png,image/jpeg,.pdf,.png,.jpg,.jpeg" multiple aria-label="补充申请材料" :disabled="uploading" @change="uploadFiles"/></label><p class="saas-subtle">PDF、PNG、JPG，每份不超过2MB，累计最多3份。</p></div></div><div class="saas-credential-box"><strong>妥善保存查询凭证</strong><p>查询凭证用于读取和补正申请，仅在当前浏览器会话内保存。请交由本单位指定人员保管。</p><div class="saas-secret">申请编号：{{credentials.businessNo}}<br/>查询凭证：{{credentials.trackingSecret}}</div></div><div v-if="application.history?.length" class="saas-panel" style="margin-top:18px"><h2>办理记录</h2><ul class="saas-history"><li v-for="(item,index) in application.history" :key="index">{{item.comment||item.content||statusText(item.action||item.status)}}<time>{{dateText(item.at||item.createdAt)}}</time></li></ul></div></template><footer class="saas-public-footer"><router-link to="/apply">提交新的开通申请</router-link><router-link to="/login">返回登录</router-link></footer></SaasPublicFrame></template>
